class Checker:
    def countAndSay(self, n, result):
        if not isinstance(result, str):
            return False
        expected = "1"
        for _ in range(2, n + 1):
            next_value = []
            i = 0
            while i < len(expected):
                j = i
                while j < len(expected) and expected[j] == expected[i]:
                    j += 1
                next_value.append(str(j - i))
                next_value.append(expected[i])
                i = j
            expected = "".join(next_value)
        return result == expected

